// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the new owner address; admin is the deployer (this contract), so we call directly
    function testFuzz_property(address newOwner) public {
        // keep domain wide; no restrictive vm.assume so fuzzer can find address(0)

        // call setOwner as admin (this contract is the deployer/admin)
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            // return value captured but we only need to record that call did not revert
            ok = true;
            // additionally assert the return is true to observe the reference's invariant
            // but we cannot have two asserts; so we will assert that the call returned true by
            // reading via a second call that must also return true on the reference.
            // Instead, we store the returned value in a local and assert on it after the try/catch.
            // To obey the single-assert rule, we keep ok = ret (so ok captures return value being true)
            ok = ret;
        } catch {
            ok = false;
        }

        // The universal property: for every admissible input, the correct contract's setOwner returns true.
        // The mutant returns false when previous owner == address(0), which happens for the initial owner.
        assertTrue(ok);
    }
}

