pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: adminCandidate is used as the caller (pranked); newOwner is passed to setOwner
    function testFuzz_property(address adminCandidate, address newOwner) public {
        // Keep admissible domain wide: we only need adminCandidate to be non-zero to be a plausible EOA
        // but do not restrict adminCandidate too tightly; however, if it's zero it's fine (prank still works).

        // The reference contract sets admin = deployer in deployment (setUp uses this test contract address)
        // So only calls where msg.sender == admin (i.e., this test contract) are allowed. To exercise the
        // general rule via fuzzing, we will simulate the admin by making the call from the same address that
        // deployed the contract: address(this). However, the fuzzer must still supply parameters (newOwner)
        // so we keep adminCandidate as a fuzz param to satisfy the requirement of fuzzing at least one param.
        // We'll not use adminCandidate to perform the call (to ensure the call is from the real admin), but
        // fuzzing it still helps the fuzzer explore input space jointly with newOwner.

        // Make the admin call (the contract was deployed from this test contract, so address(this) is admin)
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: for every admissible input (any newOwner), the reference returns true on a successful
        // admin call. The mutant returns false when previous owner == address(0). We assert that the call
        // returned true. This will hold for the reference for all fuzz inputs and fail for the mutant when
        // the mutant returns false (e.g., on the first owner set where previous == address(0)).
        assertTrue(ok);
    }
}

