pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters: adminCandidate is fuzzed to allow the fuzzer to find the deployer/admin
    // newOwner is fuzzed as the new owner to set
    function testFuzz_property(address adminCandidate, address newOwner) public {
        // Keep domain wide but ensure adminCandidate is not zero so vm.prank works sensibly
        // We do NOT constrain adminCandidate to be the actual admin; the fuzzer will find the true admin (deployer)
        // Ensure newOwner can be any address (including address(0)) — wide domain
        vm.assume(adminCandidate != address(0));

        // The reference contract's admin is the deployer of C, which is this test contract's address at setUp()
        // Deploying c in setUp() sets admin = address(this) at construction time. We must call as that admin.
        // The test harness must impersonate the original deployer (this test contract). To do that
        // we use vm.prank with address(this) so the call originates from the original admin.

        bool ok;
        // call setOwner as the admin (address(this) was the deployer and thus admin)
        try c.setOwner{gas: gasleft()}(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // General rule: reference C always returns true for admin calls to setOwner. Mutant can return false when previous==address(0).
        // Assert that the call returned true. This holds on the reference for all inputs; the mutant is broken for some input (e.g., first call when previous==address(0)).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;

    function setUp() public {
        // c's constructor sets owner and admin to msg.sender; deployer is this test contract
        c = new C();
        // admin in the contract is private and set to deployer (this contract). We'll use address(this) as admin.
        admin = address(this);
    }

    // Fuzzed parameter: candidate new owner address. The property: when called by admin, setOwner MUST return true.
    function testFuzz_property(address newOwner) public {
        // keep domain wide: allow any address including zero
        // Call as admin (this contract is admin because it deployed c)
        bool ok;
        try c.setOwner(newOwner) returns (bool ret) {
            ok = ret;
        } catch {
            // should not revert when called by admin; treat revert as failure of property
            ok = false;
        }
        // The reference implementation always returns true for admin calls; the mutant can return false when previous owner == address(0).
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz newOwner: the property ties the boolean return of setOwner to the resulting owner being non-zero
    function testFuzz_property(address newOwner) public {
        // keep domain wide; allow zero and non-zero addresses
        // call setOwner as admin (deployed contract's constructor set owner and admin to test contract)
        // in setUp we deployed C from this contract, so this contract is admin and owner initially

        // perform the call and capture success and returned bool via try/catch
        bool ok;
        bool ret;
        try c.setOwner(newOwner) returns (bool r) {
            ok = true;
            ret = r;
        } catch {
            ok = false;
            ret = false;
        }

        // The reference implementation: if the call succeeds, it returns true unconditionally and owner() == newOwner.
        // Mutant may return false even when call succeeds, specifically when previous owner was address(0).
        // We assert a universal relation: if call succeeded, the returned boolean equals (c.owner() != address(0)).
        // This holds for the reference (it returns true and owner becomes newOwner, so owner()!=0 iff newOwner!=0),
        // and is violated by the mutant for some inputs (e.g., initial previous owner == address(0)).

        // Only one assertion as required
        if (ok) {
            assertTrue(ret == (c.owner() != address(0)));
        } else {
            // If call reverted, the reference also would revert in same scenarios (but here admin should not revert).
            // Still, we assert that ok implies relation; when not ok we do not assert further.
            assertTrue(!ok == true);
        }
    }
}
